import{_ as t,o,c as r,a5 as a}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"T9 — Cutover System Health sang MongoDB","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-health-mongodb-refactor/cutover-runbook.md","filePath":"feature/system-health-mongodb-refactor/cutover-runbook.md"}'),n={name:"feature/system-health-mongodb-refactor/cutover-runbook.md"};function i(c,e,h,s,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="t9-—-cutover-system-health-sang-mongodb" tabindex="-1">T9 — Cutover System Health sang MongoDB <a class="header-anchor" href="#t9-—-cutover-system-health-sang-mongodb" aria-label="Permalink to &quot;T9 — Cutover System Health sang MongoDB&quot;">​</a></h1><p>Trạng thái: chuẩn bị, <strong>chưa thực hiện cutover</strong>. Database production vẫn phải giữ 5 bảng SQL trong rollback window.</p><h2 id="bang-chung-truoc-cutover" tabindex="-1">Bằng chứng trước cutover <a class="header-anchor" href="#bang-chung-truoc-cutover" aria-label="Permalink to &quot;Bằng chứng trước cutover&quot;">​</a></h2><ul><li>Atlas thật, database riêng <code>brandhub_monitoring_acceptance</code>: 5/5 integration test pass, 0 skipped.</li><li>Rehearsal trên PostgreSQL database riêng cùng tên và Atlas acceptance: backfill/verify pass; thêm 2 hosts, thêm collector, consume enrollment, reassign target và ghi sample microsecond; reverse-sync và verify pass, 0 discrepancies.</li><li>Manifest local: <code>tuan-research/system-health-mongodb-refactor/rehearsal-result.json</code>. PostgreSQL test và Atlas test giữ fixture sau rehearsal để kiểm tra, không reset tự động.</li><li>Các revision HEAD hiện tại chưa chứa phần refactor chưa commit: Business <code>0fa2ba2</code>, infrastructure <code>b5f99dd</code>, worker <code>a8f145d</code>. Phải build/deploy đúng working changes đã nghiệm thu, không chỉ redeploy image cũ.</li></ul><h2 id="cau-hinh-release" tabindex="-1">Cấu hình release <a class="header-anchor" href="#cau-hinh-release" aria-label="Permalink to &quot;Cấu hình release&quot;">​</a></h2><p>Compose Business đã có <code>MONITORING_STORAGE: ${MONITORING_STORAGE:-postgres}</code>. Thêm biến vào file .env không tự đổi container đang chạy; cần recreate/deploy cả fleet từ image refactor. Default vẫn postgres để không chuyển traffic trước backfill.</p><p>Database Mongo production lấy từ cấu hình Business <code>MONGODB_DATABASE</code>. Không dùng database acceptance cho cutover. Provision worker dùng cùng database production và Mongo catalog mode. Không cấp quyền catalog-write cho runtime HTTP collector.</p><h2 id="trinh-tu-thuc-hien-trong-cua-so-bao-tri" tabindex="-1">Trình tự thực hiện trong cửa sổ bảo trì <a class="header-anchor" href="#trinh-tu-thuc-hien-trong-cua-so-bao-tri" aria-label="Permalink to &quot;Trình tự thực hiện trong cửa sổ bảo trì&quot;">​</a></h2><ol><li>Khóa release image/commit refactor cho tất cả Business replica và provisioning tool. Xác nhận backup PostgreSQL và Atlas phục hồi được; ghi danh sách replica/writers.</li><li>Freeze tất cả monitoring writers: host heartbeat, collector heartbeat, health-results, invite/register và operator provisioning. Drain requests. API write bị gate phải trả lỗi bảo trì, không nhận rồi bỏ dữ liệu.</li><li>Chạy schema APPLY vào database Mongo production xác nhận rõ tên. Không chạy suite Atlas vì suite xóa dữ liệu test. Nếu collection production đã có dữ liệu khác, dừng và đối chiếu nguồn, không blind overwrite.</li><li>Chạy backfill với PostgreSQL production chỉ đọc và Mongo production ghi, sau đó verify 0 discrepancies. Ghi manifest/count/thời gian. Chỉ thao tác khi writers đã freeze.</li><li>Deploy toàn bộ Business refactor với <code>MONITORING_STORAGE=mongo</code>, giữ các cấu hình PostgreSQL để auth ADMIN vẫn hoạt động. Chuyển operator provisioning cùng đợt. Xác nhận không replica SQL-mode còn nhận request.</li><li>Smoke ADMIN list, host/collector heartbeat, result duplicate/order và enrollment trên đối tượng smoke có danh tính riêng. Mở writers, quan sát ít nhất một chu kỳ host/collector/probe; kiểm UI dữ liệu mới không chỉ snapshot cũ.</li><li>Ghi cutover time, replica/image/config, verify và smoke result. T9 chỉ tick khi có bằng chứng thực thi đủ các bước trên.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Trước khi Mongo có write mới: chuyển toàn fleet về postgres theo gate.</p><p>Sau khi Mongo có write mới: freeze/drain, reverse-export Mongo production sang PostgreSQL trong transaction, verify 0 discrepancies, kiểm host mới/enrollment consumed/owner/result timestamp, rồi chuyển fleet và provisioning về postgres. Không chỉ flip flag vì SQL snapshot đã cũ. Không reverse-sync từ acceptance vào production.</p><h2 id="sau-cutover" tabindex="-1">Sau cutover <a class="header-anchor" href="#sau-cutover" aria-label="Permalink to &quot;Sau cutover&quot;">​</a></h2><p>Theo dõi ít nhất 24 giờ và giữ rollback window đề xuất 7 ngày. Ghi lỗi/p95/throughput và SQL monitoring writes so baseline; không suy giảm tải từ số bảng.</p><p>T11 chỉ thực hiện khi có T9/T10 và hết rollback window: backup cuối, xác nhận không consumer SQL/JPA recreate, gỡ adapter rồi retirement migration có guard, không CASCADE. <strong>Không có lệnh DROP production trong phiên rehearsal này.</strong></p>',15)])])}const p=t(n,[["render",i]]);export{d as __pageData,p as default};
